              <div>
                <label className="block text-[10px] text-slate-600 mb-1">Confirm PIN</label>
                <input
                  type="password"
                  maxLength={8}
                  value={confirmPinInput}
                  onChange={(e) => setConfirmPinInput(e.target.value)}
